figures.asymptoteSource:
// The two double-angle identities read off the same point P on the unit
// circle. The chord from P to the point at twice the angle has length 2 sin x,
// and the same picture gives cos 2x as the horizontal distance.
size(229,241);
pair O = (0,0);
pair P = dir(60);
pair Q = dir(120);
draw(unitcircle, gray(0.7));
draw(O--P);
draw(O--Q);
draw(P--Q, black);
draw((O+P+Q)/3*1.1, dashed);
label("$O$", O, SW);
label("$P$", P, SE);
label("$Q$", Q, NW);
label("$2\sin x$", (P+Q)/2+(0.18,0.14), NE);
label("$\cos 2x$", (O+P+Q)/3*1.1, E);
label("$2x$", Q*0.42, NW);
label("$x$", P*0.5, SE);
label("$90^\circ$", (0.12,0.9), E);

// The Pythagorean identity, drawn. The unit circle's hypotenuse is 1, the
// legs are sin and cos, and the two Pythagorean reformulations follow by
// dividing the same picture through by a leg.
size(209,301);
pair O = (0,0);
pair P = dir(37);
draw(unitcircle, gray(0.7));
draw(O--P);
draw((O+P)/2, dashed);
draw((O+P)/2*0.5, dotted);
label("$O$", O, SW);
label("$P$", P, E);
label("$\cos^2 x$", (O+P)/2*0.5, S);
label("$1$", (O+P)/2*0.78, NW);
label("$\sin^2 x$", (O+P)/2 + (0.06,0.3), N);
label("$\sin^2 x + \cos^2 x = 1$", (0,-1.28), S);
label("$1 + \tan^2 x = \sec^2 x$", (0,1.3), N);
label("$1 + \cot^2 x = \csc^2 x$", (0.06,-1.02), S);

examples.asymptoteSource:
// The angle-addition identity as a chord-length statement. With the three
// radii at 0, x, and x+y drawn, the chord lengths from the point at x+y down
// to each of the other two are sin(x+y), sin y, and sin x in turn.
size(244,241);
pair O = (0,0);
pair A = dir(0);
pair B = dir(40);
pair C = dir(100);
draw(unitcircle, gray(0.7));
draw(O--A);
draw(O--B);
draw(O--C);
draw(C--A, black);
draw(C--B, black);
label("$O$", O, SW);
label("$A$", A, SE);
label("$B$", B, E);
label("$C$", C, NW);
label("$\sin(x+y)$", (C+A)/2+(0,-0.2), S);
label("$\sin y$", (C+B)/2+(0.14,0), NE);
label("$\sin x$", (B+A)/2+(0,-0.18), S);
label("$x$", B*0.5, S);
label("$y$", (B+C)/2*0.6, NE);
